import java.util.*;

class Solution {
    public int longestConsecutive(int[] nums) {
        int res = 0; // 保存已经找到的最长连续段长度
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }

        for (int num : set) {
            if (set.contains(num - 1)) { // 有前驱就不是起点，避免重复扫描同一段
                continue;
            }

            int length = 1;
            while (set.contains(num + 1)) {
                length++;
                num++;
            }
            if (length > res) {
                res = length;
            }
        }
        return res;
    }
}

