class Solution {
    public void moveZeroes(int[] nums) {
        // 结果直接写回nums：先收集非零元素，再在剩余位置补零
        int slow = 0;
        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != 0) {
                nums[slow] = nums[fast];
                slow++;
            }
        }
        // 有效前缀之外必须全部补零
        for (int i = slow; i < nums.length; i++) {
            nums[i] = 0;
        }
    }
}

